[CmdletBinding()]
param([Parameter(Mandatory=$true)][string[]]$Path,[string]$ProjectRoot='.',[string]$OutputPath='ES/Output/Benchmarks/resource-reader-cache-batch-perf.json')
$ErrorActionPreference='Stop'; $root=(Resolve-Path $ProjectRoot).Path; $cached=Join-Path $root '.agents/skills/es-resource-reader/scripts/Invoke-ESResourceReaderCached.ps1'; $read=Join-Path $root '.agents/skills/es-task-read-snapshot/scripts/Invoke-ESProjectionCache.ps1'; $items=New-Object Collections.Generic.List[object]
foreach($p in $Path){$source=(Resolve-Path $p).Path; $relative=$source.Substring($root.Length).TrimStart('\','/').Replace('\','/'); $ext=[IO.Path]::GetExtension($source).ToLowerInvariant(); $parser='bytes.v1'; if($ext -eq '.json'){$parser='json.v1'}elseif($ext -eq '.pdf'){$parser='pdf.probe.v1'}elseif($ext -eq '.xlsx'){$parser='xlsx.probe.v1'}elseif($ext -eq '.unitypackage'){$parser='unitypackage.python-tar.v1'}elseif($ext -in @('.png','.jpg','.jpeg','.wav','.ogg','.mp3','.mp4','.mov','.gltf','.obj','.fbx','.ttf','.otf','.woff','.woff2')){$parser='media.probe.v1'}; $null=& $cached -Path $source -ProjectRoot $root | Out-String; $sw=[Diagnostics.Stopwatch]::StartNew(); $r=& $read -Mode Read -ProjectRoot $root -SourcePath $relative -ParserId $parser -ParserVersion '1' -CacheRoot 'ES/Output/FileProjectionCache' | ConvertFrom-Json; $sw.Stop(); $items.Add([pscustomobject]@{path=$relative;status=$r.status;elapsedMs=$sw.Elapsed.TotalMilliseconds}) }
$hits=@($items|Where-Object status -eq 'hit'); $times=@($hits|ForEach-Object elapsedMs|Sort-Object); $out=[ordered]@{schemaVersion=1;benchmarkId='es-resource-reader.cache-batch-perf.v1';fileCount=$items.Count;hitCount=$hits.Count;missCount=($items.Count-$hits.Count);hitRate=if($items.Count){[math]::Round($hits.Count/$items.Count,4)}else{0};p50Ms=if($times.Count){$times[[math]::Floor(($times.Count-1)*.5)]}else{0};p95Ms=if($times.Count){$times[[math]::Floor(($times.Count-1)*.95)]}else{0};items=$items;nonClaims=@('parallel scheduler contention','Unity runtime','release')}; $dest=Join-Path $root $OutputPath; New-Item -ItemType Directory -Force -Path (Split-Path $dest)|Out-Null; $out|ConvertTo-Json -Depth 8|Set-Content -LiteralPath $dest -Encoding UTF8; $out|ConvertTo-Json -Depth 8
